            except:
                pass

            if gt_num is not None:
                # Check if solution is just the number or a simple box
                clean_sol = re.sub(r'\\boxed\{([^}]*)\}', r'\1', sol_text)
                clean_sol = clean_sol.strip()
                if re.match(r'^-?\d+$', clean_sol):
