def reward_final_answer_in_thinking(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, gt in zip(completions, answer):
        content = completion[0]['content']

        think_m = re.search(r'<thinking>(.*?)</thinking>', content, re.DOTALL)
        sol_m = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)

        if not think_m or not sol_m:
            scores.append(-0.5)
            continue

        think_text = think_m.group(1)
        sol_text = sol_m.group(1).strip()

        # Extract numeric value from solution
        sol_nums = re.findall(r'-?\d+\.?\d*', sol_text)
        if not sol_nums:
            scores.append(0.0)
            continue

        # Take the last number as the likely answer
        try:
            sol_val = float(sol_nums[-1])
        except:
            scores.append(0.0)
            continue

        # Check if this value appears in the thinking block
        # Convert to string representation that might appear in text
        sol_str = str(sol_val)
        # Also check integer representation if it's a float
        if sol_val == int(sol_val):
            sol_str_int = str(int(sol_val))
            if sol_str_int in think_text or sol_str in think_text:
                scores.append(1.0)
            else:
                scores.append(-0.5)
        else:
            if sol_str in think_text:
                scores.append(1.0)
            else:
                scores.append(-0.5)
    return scores

def reward_clear_final_answer_format(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, gt in zip(completions, answer):
        content = completion[0]['content']
        m = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)
        if not m:
            scores.append(-1.0)
            continue

        sol_text = m.group(1).strip()

        # Check if the solution is concise and clear
        # Penalize if it's too long (>100 chars) or contains too much text
        if len(sol_text) > 100:
            scores.append(-0.5)
        elif len(sol_text) < 3:
            scores.append(-0.5)
        else:
            # Check if it's a simple number or boxed expression
            clean_sol = re.sub(r'\\boxed\{([^}]*)\}', r'\1', sol_text)
            if re.match(r'^-?\d+$', clean_sol.strip()) or re.match(r'^\\frac\{\d+\}\{\d+\}$', clean_sol.strip()):
                scores.append(1.0)
            else:
                scores.append(0.5)
    return scores

def penalize_truncated_thinking(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, gt in zip(completions, answer):
        content = completion[0]['content']

        # Check if thinking tag is present but not closed
        if '<thinking>' in content and '</thinking>' not in content:
            scores.append(-1.5)
            continue

        # Check if solution tag is present but not closed
        if '<solution>' in content and '</solution>' not in content:
            scores.append(-1.5)
            continue

        # Check if the content ends abruptly inside a thinking block
        think_m = re.search(r'<thinking>(.*?)</thinking>', content, re.DOTALL)
        if think_m:
            think_text = think_m.group(1)
            # If thinking ends with an incomplete sentence or equation
            if think_text.rstrip().endswith(('=', '+', '-', '*', '/', '\\frac', '\\sqrt')):
                scores.append(-1.0)
            else:
                scores.append(0.0)
        else:
            scores.append(0.0)
    return scores

def reward_integer_answer_consistency(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, gt in zip(completions, answer):
        try:
            text = completion[0]['content']
            m_sol = re.search(r'<solution>(.*?)</solution>', text, re.DOTALL)
            if not m_sol:
                scores.append(-1.0)
                continue

            sol_text = m_sol.group(1).strip()

            # Extract the last number in the solution
            nums = re.findall(r'-?\d+(?:\.\d+)?', sol_text)
            if not nums:
                scores.append(-0.5)
                continue

            last_num_str = nums[-1]

            # Check if it's a decimal
            if '.' in last_num_str:
                # If the answer is a decimal, check if it's an integer value
                try:
                    val = float(last_num_str)
                    if val.is_integer():
                        # It's an integer written as float, e.g., 5.0
                        scores.append(0.0)
                    else:
                        # Non-integer decimal
                        scores.append(-1.0)
                except:
                    scores.append(-0.5)
            else:
                # It's an integer string
                scores.append(1.0)
        except Exception:
            scores.append(-1.0)
    return scores

